"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[56699],{9648:e=>{e.exports=JSON.parse('{"functions":[{"name":"prepareAssembly","desc":"Prepare a cloned throwable to fly as one rigid, falling body and land predictably:\\nun-anchor every part (an assembly with ANY anchored part is immovable); keep the\\nroot massed (so gravity arcs it) while making cosmetic descendants massless; apply\\nthe low-elasticity / high-friction physics (small bounce, no slide); and weld every\\ndescendant to the root so a multi-part model flies + lands as one piece. For a\\nsingle-part asset (the current grenade + C4) there are no descendants, so the weld\\nand massless-child steps are inert.","params":[{"name":"clone","desc":"","lua_type":"Instance"},{"name":"root","desc":"","lua_type":"BasePart"},{"name":"physics","desc":"","lua_type":"PhysicalProperties"}],"returns":[],"function_type":"static","source":{"line":158,"path":"src/ServerStorage/SharedModules/ServerProjectile.luau"}},{"name":"spawnThrowable","desc":"Spawn a physics-driven, replicated throwable. Returns the cloned instance\\n(BasePart or Model) or nil if the template is missing/invalid.\\n\\nEvery throwable shares one arc \u2014 `prepareAssembly` + launch \u2014 and one mover\\n(`installSettle`): arc, then plant flat once it has contacted a world surface and come\\nto rest. The `rest` mode only sets bounciness:\\n\\n            \\"Bounce\\" keeps one small hop before settling (grenade). Both arc, plant\\n            only at rest (never mid-flight), and pass through every character via the\\n            WeaponProjectile collision group.\\n              (e.g. the thrower\'s character; characters are skipped regardless).","params":[{"name":"templateName","desc":"","lua_type":"string"},{"name":"origin","desc":"","lua_type":"Vector3"},{"name":"direction","desc":"","lua_type":"Vector3"},{"name":"speed","desc":"","lua_type":"number"},{"name":"rest","desc":"","lua_type":"\\"Stick\\" lands dead with no bounce and plants where it settles (C4);"},{"name":"ignore","desc":"","lua_type":"instances whose descendants never count as a landing surface"}],"returns":[{"desc":"","lua_type":"Instance?\\n"}],"function_type":"static","source":{"line":233,"path":"src/ServerStorage/SharedModules/ServerProjectile.luau"}},{"name":"spawnRocket","desc":"Spawn an anchored, replicated rocket cosmetic at `cframe`. The caller (WeaponServer)\\nsteps its CFrame along the authoritative FastCast cast and destroys it on hit.\\nCanQuery=false so the authoritative ray never hits the cosmetic itself.","params":[{"name":"templateName","desc":"","lua_type":"string"},{"name":"cframe","desc":"","lua_type":"CFrame"}],"returns":[{"desc":"","lua_type":"BasePart?\\n"}],"function_type":"static","source":{"line":286,"path":"src/ServerStorage/SharedModules/ServerProjectile.luau"}}],"properties":[],"types":[],"name":"ServerProjectile","desc":"Spawns and owns server-authoritative, REPLICATED projectile instances cloned\\nfrom ReplicatedStorage/WeaponAssets into workspace/ServerProjectiles. Two\\nmovers: a physics mover for throwables (a server-owned rigid body that arcs,\\nthen plants flat once it lands and comes to rest \u2014 C4 lands dead, the grenade\\nsettles after a small bounce) and a rocket spawner returning an anchored part the\\ncaller steps along its authoritative FastCast2 cast. Damage/explosions are handled\\nby the caller (WeaponServer), never here.","realm":["Server"],"source":{"line":14,"path":"src/ServerStorage/SharedModules/ServerProjectile.luau"}}')}}]);